/// <summary>
/// Controller of one runtime task of the mass trade agreement price update: a bundle of items, or the summary task.
/// </summary>
public class DYLO_TradeAgreementPriceAdjTaskController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Creates a task controller that runs a method of <c>DYLO_TradeAgreementPriceAdjService</c>.
/// </summary>
/// <param name = "_methodName">The service method: processBundle or finalizeRun.</param>
/// <returns>The task controller.</returns>
public static DYLO_TradeAgreementPriceAdjTaskController newFromMethod(IdentifierName _methodName)
{
    DYLO_TradeAgreementPriceAdjTaskController controller = new DYLO_TradeAgreementPriceAdjTaskController(
        classStr(DYLO_TradeAgreementPriceAdjService),
        _methodName,
        SysOperationExecutionMode::Synchronous);

    controller.parmShowDialog(false);

    return controller;
}
